"""Consume payloads generated by the real Java producer and serializer."""
import json
from pathlib import Path
from urllib.request import Request, urlopen

import pytest

from god_bridge.bridge import BridgeConfig, GodBridge
from god_bridge.event_http import start_event_server
from god_bridge.story import watch_matches


def test_java_payloads_cross_the_http_boundary_and_match_watches(tmp_path):
    fixture = Path(__file__).resolve().parents[1] / "paper-plugin/build/contract/events.json"
    if not fixture.exists():
        pytest.skip("Run the Gradle build first to generate Java event contract payloads")
    events = json.loads(fixture.read_text())
    bridge = GodBridge(BridgeConfig(state_file=str(tmp_path / "state.json"), event_port=0, event_token="contract-test", dry_run=True))
    server = start_event_server(bridge)
    try:
        for event in events:
            request = Request(f"http://127.0.0.1:{server.server_port}/events", data=json.dumps(event).encode(), headers={"Authorization": "Bearer contract-test"})
            with urlopen(request) as response:
                assert response.status == 202
                accepted = json.load(response)["event"]
            assert accepted["schema_version"] == 1
            assert "\x01" in accepted["message"]
            if event["type"] in {"block_place", "block_break"}:
                watch = {"kind": event["type"], "dimension": "minecraft:overworld", "position": "10 64 10", "block": "minecraft:gold_block"}
                assert watch_matches(watch, accepted)
                assert not watch_matches({**watch, "dimension": "minecraft:the_nether"}, accepted)
        assert bridge.latest_event_id() == len(events)
    finally:
        server.shutdown()
        server.server_close()
